import { useState } from 'react'
import './App.css'

function App() {
  const [display, setDisplay] = useState('0')
  const [previousValue, setPreviousValue] = useState(null)
  const [operation, setOperation] = useState(null)
  const [waitingForOperand, setWaitingForOperand] = useState(false)

  const inputDigit = (digit) => {
    if (waitingForOperand) {
      setDisplay(String(digit))
      setWaitingForOperand(false)
    } else {
      setDisplay(display === '0' ? String(digit) : display + digit)
    }
  }

  const inputDecimal = () => {
    if (waitingForOperand) {
      setDisplay('0.')
      setWaitingForOperand(false)
    } else if (display.indexOf('.') === -1) {
      setDisplay(display + '.')
    }
  }

  const clear = () => {
    setDisplay('0')
    setPreviousValue(null)
    setOperation(null)
    setWaitingForOperand(false)
  }

  const performOperation = (nextOperation) => {
    const inputValue = parseFloat(display)

    if (previousValue === null) {
      setPreviousValue(inputValue)
    } else if (operation) {
      const currentValue = previousValue || 0
      const newValue = calculate(currentValue, inputValue, operation)

      setDisplay(String(newValue))
      setPreviousValue(newValue)
    }

    setWaitingForOperand(true)
    setOperation(nextOperation)
  }

  const calculate = (firstValue, secondValue, operation) => {
    switch (operation) {
      case '+':
        return firstValue + secondValue
      case '-':
        return firstValue - secondValue
      case '*':
        return firstValue * secondValue
      case '/':
        return firstValue / secondValue
      case '=':
        return secondValue
      default:
        return secondValue
    }
  }

  const handleEquals = () => {
    const inputValue = parseFloat(display)

    if (previousValue !== null && operation) {
      const newValue = calculate(previousValue, inputValue, operation)
      setDisplay(String(newValue))
      setPreviousValue(null)
      setOperation(null)
      setWaitingForOperand(true)
    }
  }

  const toggleSign = () => {
    const value = parseFloat(display)
    setDisplay(String(value * -1))
  }

  const inputPercent = () => {
    const value = parseFloat(display)
    setDisplay(String(value / 100))
  }

  return (
    <div className="calculator">
      <div className="calculator-display">{display}</div>
      <div className="calculator-keypad">
        <div className="calculator-row">
          <button className="calculator-key key-clear" onClick={clear}>AC</button>
          <button className="calculator-key key-sign" onClick={toggleSign}>±</button>
          <button className="calculator-key key-percent" onClick={inputPercent}>%</button>
          <button className="calculator-key key-operator" onClick={() => performOperation('/')}>÷</button>
        </div>
        <div className="calculator-row">
          <button className="calculator-key" onClick={() => inputDigit(7)}>7</button>
          <button className="calculator-key" onClick={() => inputDigit(8)}>8</button>
          <button className="calculator-key" onClick={() => inputDigit(9)}>9</button>
          <button className="calculator-key key-operator" onClick={() => performOperation('*')}>×</button>
        </div>
        <div className="calculator-row">
          <button className="calculator-key" onClick={() => inputDigit(4)}>4</button>
          <button className="calculator-key" onClick={() => inputDigit(5)}>5</button>
          <button className="calculator-key" onClick={() => inputDigit(6)}>6</button>
          <button className="calculator-key key-operator" onClick={() => performOperation('-')}>−</button>
        </div>
        <div className="calculator-row">
          <button className="calculator-key" onClick={() => inputDigit(1)}>1</button>
          <button className="calculator-key" onClick={() => inputDigit(2)}>2</button>
          <button className="calculator-key" onClick={() => inputDigit(3)}>3</button>
          <button className="calculator-key key-operator" onClick={() => performOperation('+')}>+</button>
        </div>
        <div className="calculator-row">
          <button className="calculator-key key-zero" onClick={() => inputDigit(0)}>0</button>
          <button className="calculator-key" onClick={inputDecimal}>.</button>
          <button className="calculator-key key-equals" onClick={handleEquals}>=</button>
        </div>
      </div>
    </div>
  )
}

export default App

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue',
    sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#root {
  width: 100%;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
}

.calculator {
  background: #1e1e1e;
  border-radius: 20px;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  padding: 20px;
  width: 100%;
  max-width: 400px;
}

.calculator-display {
  background: #2d2d2d;
  color: #ffffff;
  font-size: 3rem;
  text-align: right;
  padding: 30px 20px;
  border-radius: 10px;
  margin-bottom: 20px;
  min-height: 100px;
  display: flex;
  align-items: center;
  justify-content: flex-end;
  word-wrap: break-word;
  word-break: break-all;
  font-weight: 300;
}

.calculator-keypad {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.calculator-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.calculator-key {
  background: #505050;
  color: #ffffff;
  border: none;
  border-radius: 50%;
  font-size: 1.5rem;
  padding: 0;
  cursor: pointer;
  transition: all 0.2s ease;
  aspect-ratio: 1;
  min-height: 70px;
  font-weight: 400;
}

.calculator-key:hover {
  background: #606060;
  transform: scale(1.05);
}

.calculator-key:active {
  transform: scale(0.95);
}

.key-clear,
.key-sign,
.key-percent {
  background: #a5a5a5;
  color: #1e1e1e;
  font-weight: 500;
}

.key-clear:hover,
.key-sign:hover,
.key-percent:hover {
  background: #b5b5b5;
}

.key-operator {
  background: #ff9500;
  font-weight: 500;
}

.key-operator:hover {
  background: #ffaa33;
}

.key-equals {
  background: #ff9500;
  font-weight: 500;
}

.key-equals:hover {
  background: #ffaa33;
}

.key-zero {
  grid-column: span 2;
  border-radius: 35px;
}

@media (max-width: 480px) {
  .calculator {
    max-width: 350px;
  }

  .calculator-display {
    font-size: 2.5rem;
    padding: 25px 15px;
    min-height: 80px;
  }

  .calculator-key {
    font-size: 1.3rem;
    min-height: 60px;
  }
}

